brand.css:
.t2-txt{position:absolute;left:40px;right:40px;top:var(--t2-y,930px);display:flex;flex-direction:column;align-items:center;text-align:center;gap:6px}
.t2-ttl{font-family:var(--f-title);font-weight:700;font-size:var(--t2-size,118px);line-height:1.25;letter-spacing:-.01em;white-space:nowrap;
  background:linear-gradient(180deg,#FE9545 0%,#FFA75A 45%,#FDC787 100%);-webkit-background-clip:text;background-clip:text;color:transparent;
  filter:drop-shadow(0 0 10px rgba(255,140,60,.75)) drop-shadow(0 0 34px rgba(255,120,40,.45))}
.t2-sub{font-family:var(--f-sub);font-weight:300;font-size:var(--t2-sub,46px);line-height:1.3;color:rgba(255,255,255,.94);text-shadow:0 2px 10px rgba(0,0,0,.45);white-space:nowrap}
.t2-sub b{font-weight:600}
.t2-bar{display:inline-block;height:.13em;width:0;vertical-align:.18em;border-radius:.07em;background:linear-gradient(90deg,#FFB271,#FE9545)}
.t2-type{clip-path:inset(-30% 0 -30% 0)}
.t2-hex{position:absolute;left:0;top:0;width:1080px;height:1920px;overflow:visible}
.t2-hex .glint{stroke:#FFF3E0;stroke-width:6;stroke-dasharray:.07 .93;filter:drop-shadow(0 0 8px #FFD2A6)}
.t2-hex path,.t2-hex polygon{fill:none;stroke:#FF9A4A;stroke-width:4;filter:drop-shadow(0 0 6px #FF8A3D) drop-shadow(0 0 18px rgba(255,120,40,.7))}
.t2-hex .dash{stroke:#fff;stroke-width:2;stroke-dasharray:6 10;opacity:.7;filter:none}
.t2-hex circle{fill:#FFD2A6;filter:drop-shadow(0 0 6px #FF9A4A)}
.t2-ring{position:absolute;left:150px;top:236px;width:780px;height:780px}
.t2-ring svg{width:100%;height:100%;overflow:visible}
.t2-ring .tk{fill:none;stroke:#FFE2C4;stroke-width:5;stroke-dasharray:3 26;filter:drop-shadow(0 0 5px #FF9A4A)}
.t2-ring .ln{fill:none;stroke:#FF9A4A;stroke-width:2.5;opacity:.85;filter:drop-shadow(0 0 8px #FF8A3D)}
.t2-ring .dt{fill:#FFF1E0;filter:drop-shadow(0 0 6px #FFB271)}
.t2-icon{position:absolute;left:50%;top:var(--t2-iy,1560px);width:230px;height:230px;margin-left:-115px;color:#FFB271;filter:drop-shadow(0 0 12px rgba(255,140,60,.8))}
.t2-icon svg{width:100%;height:100%}
.t2-corner{position:absolute;width:420px;height:420px;border-radius:50%;background:rgba(255,255,255,.10);border:2px solid rgba(255,255,255,.35);
  -webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px);box-shadow:inset 0 0 40px rgba(255,255,255,.12)}
.t2-corner.tr{right:-190px;top:-190px}.t2-corner.bl{left:-190px;bottom:-110px}
.t2-corner b{position:absolute;font-family:var(--f-title);font-weight:700;font-size:150px;line-height:1;color:#fff;text-shadow:0 0 22px rgba(255,255,255,.55)}
.t2-corner.tr b{left:70px;bottom:60px}.t2-corner.bl b{right:90px;top:70px}
.t2-3d{position:absolute;font-family:var(--f-title);font-weight:800;font-size:var(--t2-3ds,330px);line-height:1;letter-spacing:-.04em;color:#F38A3F;
  background:linear-gradient(180deg,#FFB070 0%,#F2843A 55%,#C9601F 100%);-webkit-background-clip:text;background-clip:text;color:transparent;
  filter:drop-shadow(5px 5px 0 #A8501B) drop-shadow(5px 5px 0 #8E4316) drop-shadow(8px 14px 18px rgba(0,0,0,.55))}
.t2-ask{position:absolute;left:50%;top:var(--t2-ay,1060px);transform:translateX(-50%);min-width:560px;padding:40px 46px 30px;border-radius:70px;background:#fff;
  box-shadow:0 0 0 10px rgba(255,255,255,.25),0 18px 50px rgba(0,0,0,.45);text-align:center;font-family:var(--f-sub);color:#1B1B1B}
.t2-ask .q{position:absolute;left:50%;top:-50px;width:96px;height:96px;margin-left:-48px;border-radius:50%;background:#F07A3A;color:#fff;
  font-family:var(--f-title);font-weight:700;font-size:58px;line-height:96px;box-shadow:0 0 0 8px rgba(240,122,58,.25)}
.t2-ask .l1{font-weight:400;font-size:34px;white-space:nowrap}
.t2-ask .l2{font-weight:700;font-size:40px;margin-top:4px;white-space:nowrap}
.t2-arch{position:absolute;left:194px;width:692px;top:var(--t2-cy,1138px);height:900px;border-radius:346px 346px 0 0;
  background:linear-gradient(180deg,rgba(255,255,255,.20),rgba(255,255,255,.08));border:2px solid rgba(255,255,255,.38);border-bottom:0;
  -webkit-backdrop-filter:blur(18px) saturate(1.1);backdrop-filter:blur(18px) saturate(1.1);display:flex;flex-direction:column;align-items:center;padding-top:110px;gap:8px}
.t2-arch.down{top:auto;bottom:var(--t2-cb,1290px);border-radius:0 0 346px 346px;border:2px solid rgba(255,255,255,.38);border-top:0;justify-content:flex-end;padding:0 0 230px}
.t2-arch .s{font-family:var(--f-sub);font-weight:300;font-size:46px;color:#fff}
.t2-arch .k{font-family:var(--f-title);font-weight:700;font-size:96px;line-height:1.2;white-space:nowrap;background:linear-gradient(180deg,#FE9545,#FDC787);
  -webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 0 10px rgba(255,140,60,.7))}
.t2-arch .x{width:170px;height:170px;margin-top:100px;position:relative}
.t2-arch .x::before,.t2-arch .x::after{content:"";position:absolute;left:50%;top:50%;width:190px;height:30px;margin:-15px 0 0 -95px;border-radius:15px;
  background:#FF9A4A;box-shadow:0 0 18px rgba(255,140,60,.8)}
.t2-arch .x::before{transform:rotate(45deg)}.t2-arch .x::after{transform:rotate(-45deg)}
.t2-pill{display:inline-block;margin-top:34px;padding:16px 150px 22px;border-radius:70px;background:linear-gradient(180deg,rgba(40,30,24,.55),rgba(20,14,10,.55));
  border:3px solid rgba(255,214,160,.75);box-shadow:0 0 22px rgba(255,170,90,.45),inset 0 0 18px rgba(255,214,160,.2);
  -webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);font-family:var(--f-title);font-weight:600;font-size:66px;color:#fff;white-space:nowrap}
.t2-brand{position:absolute;left:-420px;right:-420px;top:var(--t2-by,1426px);height:1400px;border-radius:50% 50% 0 0;
  background:radial-gradient(120% 60% at 50% 0%,#FFA766 0%,#F57A35 45%,#E2672A 100%);box-shadow:0 -10px 50px rgba(255,120,40,.45);
  display:flex;flex-direction:column;align-items:center;padding-top:150px}
.t2-brand b{font-family:"Josefin Sans",var(--f-label);font-weight:400;font-size:var(--t2-bs,178px);line-height:1;letter-spacing:.02em;color:#fff;white-space:nowrap}
.t2-brand i{display:block;width:620px;height:3px;margin-top:40px;background:linear-gradient(90deg,transparent,rgba(255,255,255,.85),transparent)}
.t2-social{position:absolute;left:50%;top:var(--t2-sy,1024px);transform:translateX(-50%);height:90px;padding:0 34px;border-radius:16px;background:#F2763A;
  display:flex;align-items:center;gap:18px;color:#fff;font-family:var(--f-label);font-weight:500;font-size:42px;white-space:nowrap;box-shadow:0 8px 24px rgba(0,0,0,.35)}
.t2-social::after{content:"";position:absolute;left:50%;bottom:-14px;margin-left:-14px;border:14px solid transparent;border-bottom:0;border-top-color:#F2763A}
.t2-social svg{width:46px;height:46px}
.t2-metal{position:absolute;left:130px;top:var(--t2-my,350px);font-family:"Oswald",var(--f-label);font-weight:500;font-size:250px;line-height:.86;letter-spacing:-.01em;
  text-transform:lowercase;background:linear-gradient(180deg,rgba(255,255,255,.55),rgba(190,170,150,.18) 60%,rgba(255,230,200,.45));-webkit-background-clip:text;background-clip:text;color:transparent;
  -webkit-text-stroke:2px rgba(255,240,225,.75);filter:drop-shadow(0 6px 18px rgba(0,0,0,.45))}
.t2-metal span{display:block}
.t2-metal .m2{transform:scaleY(1.18);transform-origin:50% 0}
.t2-frame{position:absolute;left:108px;top:350px;width:842px;height:580px}
.t2-frame::before,.t2-frame::after{content:"";position:absolute;width:110px;height:110px;border:3px solid rgba(255,255,255,.8)}
.t2-frame::before{right:0;top:0;border-left:0;border-bottom:0}.t2-frame::after{left:0;bottom:0;border-right:0;border-top:0}
.t2-big{position:absolute;left:0;right:0;top:var(--t2-gy,170px);text-align:center;font-family:"Oswald",var(--f-title);font-weight:400;font-size:var(--t2-gs,800px);line-height:1;letter-spacing:-.02em;
  color:rgba(255,255,255,.06);-webkit-text-stroke:5px rgba(255,236,215,.75);filter:drop-shadow(0 0 14px rgba(255,200,150,.35))}
.t2-hand{position:absolute;left:0;right:0;top:var(--t2-hy,190px);text-align:center;font-family:"Great Vibes",cursive;font-size:var(--t2-hs,230px);line-height:1;color:#FF9A4A;
  filter:drop-shadow(0 0 10px rgba(255,140,60,.8))}
